<?php

namespace Didww\Item\SmsTrunkConfiguration;

use Didww\Enum\SmsServerLocation;

/**
 * The customer connects to DIDWW as an SMPP ESME.
 */
class SmppEsme extends Base
{
    /**
     * Generated by DIDWW and never sent on write.
     */
    public const READ_ONLY_ATTRIBUTES = [
        'system_id',
        'password',
    ];

    protected const LIST_ATTRIBUTES = ['allowed_ips'];

    protected array $sensitiveAttributes = [
        'system_id',
        'password',
    ];

    public function getType(): string
    {
        return 'smpp_esme';
    }

    public function getSystemType(): ?string
    {
        return $this->attribute('system_type');
    }

    /**
     * Max 12 characters; null clears it.
     */
    public function setSystemType(?string $systemType)
    {
        $this->attributes['system_type'] = $systemType;
    }

    /**
     * @return string[]|null
     */
    public function getAllowedIps(): ?array
    {
        return $this->attribute('allowed_ips');
    }

    /**
     * @param string[]|null $allowedIps addresses the ESME may bind from
     */
    public function setAllowedIps(?array $allowedIps)
    {
        $this->attributes['allowed_ips'] = null === $allowedIps ? null : array_values($allowedIps);
    }

    public function getServerLocation(): SmsServerLocation|string|null
    {
        return $this->enumAttribute('server_location', SmsServerLocation::class);
    }

    /**
     * Required when the trunk is created.
     */
    public function setServerLocation(SmsServerLocation|string $serverLocation)
    {
        $this->setEnumAttribute('server_location', $serverLocation);
    }

    /**
     * Generated SMPP system_id to bind with.
     */
    public function getSystemId(): ?string
    {
        return $this->attribute('system_id');
    }

    /**
     * Generated SMPP bind password.
     */
    public function getPassword(): ?string
    {
        return $this->attribute('password');
    }
}
